/*!
 * wega-music-endless1.js - ENDLESS add-on for the Wega's Challenge music pack.
 * The game loads it by itself when an ENDLESS run needs it (it is not in index.html): it registers a lazy
 * "endless1" track with WegaMusic, decoded only while it plays. The music changes every 10 floors
 * (Endless, then Endless 1-5); the shop between floors has its own theme.
 * ENDLESS 1 (floors 11-20) - supplied by the player. Loops with a crossfade from 150.0 s (where its reverb tail starts) back to the top.
 */
(function (global) {
  "use strict";
  var D = global.WEGA_MUSIC_DATA, W = global.WegaMusic;
  if (!D || !W) { if (global.console) console.warn("[wega-music-endless1.js] load wega-music.js first"); return; }
  D.endless1 = {
    title: "ENDLESS 1 (floors 11-20)",
    credit: "supplied by the player",
    duration: 153.130,
    loopStart: 0.0,
    loopEnd: 150.0,
    xfade: 2.5,
    gain: 0.83,
    lazy: true,
    src: "data:audio/mpeg;base64,"
  };
  if (W.tracks.indexOf("endless1") < 0) W.tracks.push("endless1");
  if (W.onPack) W.onPack("endless1");
})(typeof window !== "undefined" ? window : globalThis);
